{
  "window_id": "w0037",
  "observed_failures": [
    {
      "filename": "034.jpg",
      "field": "date",
      "predicted": "2018-08-09",
      "visible_evidence": "Receipt header shows 'Date: 09/03/2018' in Malaysian DD/MM/YYYY locale; date also repeats on 'Receipt #' context. Prediction corresponds to parsing '09/08/2018' (OCR digit confusion 3↔8) under DD/MM/YYYY.",
      "failure_mode": "ocr_digit_confusion_on_date_with_no_cross_variant_validation"
    },
    {
      "filename": "074.jpg",
      "field": "total_amount",
      "predicted": "702.00",
      "visible_evidence": "GL Handicraft & Tailoring receipt: 'Subtotal 102.00', 'Total Incl. of GST 102.00', 'Total Amt Rounded 102.00', 'Payment 102.00'. Predicted 702.00 indicates OCR misread leading '1' as '7' (or preceding char glued to amount).",
      "failure_mode": "ocr_digit_confusion_1_to_7_with_insufficient_variant_voting_or_sanity_check"
    },
    {
      "filename": "077.jpg",
      "field": "total_amount",
      "predicted": "23.26",
      "visible_evidence": "Banh Mi Cafe shows 'Total (Inclusive of GST): 23.26', 'Rounding Adj: -0.01', 'TOTAL: 23.25'. Agent returned the pre-rounding value matched by 'Total' keyword; the final bold 'TOTAL:' after the rounding line is the authoritative total.",
      "failure_mode": "ignores_final_total_after_rounding_adjustment_prefers_earlier_total_keyword_match"
    },
    {
      "filename": "078.jpg",
      "field": "total_amount",
      "predicted": null,
      "visible_evidence": "Thai Delicious Restaurant receipt shows 'Total: 92.80', 'Grand Total: 92.80'. Window steps show OCR variants produce 'GrandTotal.' (no space), 'Grand Total  a 92.80', 'Grand Total —— ~\"\"92 80' (space-separated digits), 'Grand Total SRT' etc. Current GRAND\\s+TOTAL regex and NUM_RE both fail on these spellings.",
      "failure_mode": "keyword_regex_too_strict_for_compound_and_digit_formatting_variants"
    }
  ],
  "root_causes": [
    {
      "id": "rc_final_total_after_rounding",
      "description": "The total-extraction tier logic does not special-case a 'TOTAL' that appears after a 'Rounding Adj'/'Rounded'/'Total After Rounding' line. 'Last match in tier' is not sufficient when both candidates share the same tier priority but one is pre-rounding and one is post-rounding.",
      "evidence": "077.jpg: prediction 23.26 corresponds to 'Total (Inclusive of GST): 23.26'; the correct final 'TOTAL: 23.25' sits below 'Rounding Adj: -0.01'."
    },
    {
      "id": "rc_compound_keyword_and_spaced_digits",
      "description": "Keyword regexes require whitespace between words ('GRAND\\s+TOTAL') and the numeric regex requires an unbroken decimal (e.g. '92.80'), so common OCR corruptions like 'GrandTotal', 'Grand Total 92 80', or 'NETTOTAL' never match, even though humans can read the number.",
      "evidence": "078.jpg: variants produced 'GrandTotal. = SSCS 92.80' and 'Grand Total —— 92 80' but no candidate was emitted."
    },
    {
      "id": "rc_single_variant_digit_misread",
      "description": "Per-field OCR relies on a small fixed set of preprocessing variants and uses frequency voting at the best priority tier, but when all variants share the same character misread (e.g. '1'→'7' on a bold stylized digit), voting cannot repair it and there is no numeric sanity check against item lines or sub-total/total consistency.",
      "evidence": "074.jpg: all extracted variants converge on '702.00' despite subtotal/payment/rounded-total all being 102.00; no consistency check between sub-total, total and payment is performed."
    },
    {
      "id": "rc_date_no_cross_validation",
      "description": "Date extraction returns the first regex-matching date in reading order; it does not vote across OCR variants or cross-check against other date occurrences in the receipt body (e.g. cashier line, print time, invoice date).",
      "evidence": "034.jpg: OCR mis-recognized '09/03/2018' as '09/08/2018' in the chosen variant and no second occurrence was used to correct it."
    },
    {
      "id": "rc_skill_lacks_receipt_specific_patterns",
      "description": "Original image-ocr SKILL.md documents only generic Tesseract usage with multi-pass OCR; it does not prescribe the receipt-specific priority/exclusion pipeline, rounding-adjustment handling, compound-keyword tolerance, cross-variant voting, or null-safe row emission that the task requires.",
      "evidence": "Original image-ocr.md has no structured-field extraction section; the candidate revision added one but still omits final-TOTAL-after-rounding, compound-keyword, and cross-variant voting rules."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "Structured field extraction section (candidate version) lacks explicit rule: after any 'ROUNDING ADJ', 'ROUNDED', 'ROUND(ING)' or 'TOTAL AFTER ROUNDING' line, the next matching TOTAL/GRAND TOTAL supersedes earlier same-tier matches."
    },
    {
      "skill": "image-ocr",
      "defect": "Total-keyword regexes are whitespace-strict ('GRAND\\s+TOTAL', 'NET\\s*TOTAL'); no tolerance for OCR-glued spellings like 'GRANDTOTAL', 'NETTOTAL', 'GRANDTOT', 'GRAND TOTA.' etc."
    },
    {
      "skill": "image-ocr",
      "defect": "Numeric pattern only matches canonical 'N.NN'; it does not attempt digit-space-joining (e.g. '92 80' → '92.80') or decimal-point repair ('92:80' → '92.80') on keyword-bearing lines where a two-decimal amount is strongly expected."
    },
    {
      "skill": "image-ocr",
      "defect": "No explicit guidance on cross-variant voting and cross-occurrence validation for the date field; the skill describes only a single DATE_PATTERNS loop that stops at the first match."
    },
    {
      "skill": "image-ocr",
      "defect": "Preprocessing recipe is light: autocontrast, invert, sharpen, threshold mentioned but no strong recommendation to also include a 3x upscale + PSM 4 pass, which the trajectory shows is decisive for faded/low-DPI receipts (e.g. 078)."
    },
    {
      "skill": "image-ocr",
      "defect": "Exclusion list for total extraction does not include column-header lines ('DESCRIPTION', 'QTY PRICE AMOUNT') or transaction-summary items ('CASH RECEIVED', 'CASH PAYMENT', 'TOTAL SAVINGS', 'TOTAL ITEMS', 'ITEM COUNT'), causing header/row amounts to be picked up as fallback totals."
    },
    {
      "skill": "image-ocr",
      "defect": "No numeric consistency check: the skill does not advise comparing the chosen total against sub-total and payment/change values from the same receipt to reject obvious outliers (helps catch '1'→'7' style misreads)."
    },
    {
      "skill": "xlsx",
      "defect": "Candidate xlsx skill already covers strict-schema outputs and real-null handling correctly for this task; no new defect surfaced in this window, but a brief explicit note that unparseable fields must be written as Python None (not empty string, not NaN) could be reinforced with a one-line reminder next to the extraction-pipeline pattern."
    }
  ],
  "repair_recommendations": [
    {
      "skill": "image-ocr",
      "section": "Structured Field Extraction (Receipts / Forms)",
      "change": "Add a 'Rounding-aware total selection' subsection: when scanning for totals, detect lines matching /ROUND(ING|ED)|ROUNDING\\s*ADJ|TOTAL\\s*AFTER\\s*ROUND/i; if such a line exists, prefer TOTAL/GRAND TOTAL matches that occur AFTER it over same-tier matches BEFORE it. Document the rationale (final printed total supersedes pre-rounding 'Total (Inclusive of GST)')."
    },
    {
      "skill": "image-ocr",
      "section": "Keyword Priority and Exclusions",
      "change": "Broaden priority regexes to tolerate OCR-glued forms: e.g. r'GRAND[\\s\\-]*TOTAL', r'NET[\\s\\-]*TOTAL', r'TOTAL[\\s]*(RM|AMOUNT|DUE)?', and r'GRAND\\s*TOTA\\.?' for truncations. Keep tier order unchanged."
    },
    {
      "skill": "image-ocr",
      "section": "Keyword Priority and Exclusions",
      "change": "Extend EXCLUSIONS to include: 'TOTAL SAVINGS', 'TOTAL ITEMS', 'TOTAL QTY', 'ITEM COUNT', 'CASH RECEIVED', 'CASH PAYMENT', 'TOTAL (EXCLUDING', and column-header lines matching /DESCRIPTION/ or /(QTY|PRICE)\\s+AMOUNT/. Note that exclusions must be tested before tier matching."
    },
    {
      "skill": "image-ocr",
      "section": "Structured Field Extraction (Receipts / Forms)",
      "change": "Add a 'Numeric repair on keyword lines' subsection: on a line that matched a priority keyword but produced no N.NN match, attempt to (a) join digit-space-digit pairs into a decimal when exactly two trailing digits follow a space ('92 80' → '92.80'), and (b) treat ':' between digits as '.' ('92:80' → '92.80'). Only apply this on keyword-bearing lines, never on body lines."
    },
    {
      "skill": "image-ocr",
      "section": "Multi-Pass OCR Strategy",
      "change": "Promote a concrete recommended variant set for receipts: (1) default PSM 3, (2) grayscale+autocontrast PSM 6, (3) 2× upscale + autocontrast PSM 6, (4) 3× upscale + autocontrast PSM 4. Call out that (4) is often the only pass that recovers faded/low-DPI 'Grand Total' lines."
    },
    {
      "skill": "image-ocr",
      "section": "Structured Field Extraction (Receipts / Forms)",
      "change": "Add a 'Cross-variant voting' subsection: collect (tier, value) candidates from every OCR variant, pick the lowest tier that has any candidate anywhere, then return the value with the highest cross-variant frequency within that tier (tie-break by earliest-appearance). Explicitly document this as the recommended selection policy, replacing 'first match wins'."
    },
    {
      "skill": "image-ocr",
      "section": "Date Extraction and ISO Normalization",
      "change": "Add a 'Date voting' paragraph: collect all regex matches across all OCR variants, normalize each to ISO using the existing DATE_PATTERNS list, and return the ISO date with the highest frequency (ties broken by earliest reading-order occurrence). Note the Malaysian locale convention (DD/MM/YYYY has priority over MM/DD/YYYY for ambiguous digit pairs)."
    },
    {
      "skill": "image-ocr",
      "section": "Structured Field Extraction (Receipts / Forms)",
      "change": "Add a short 'Numeric consistency sanity check' note: when a candidate total is chosen, compare it against any detected SUBTOTAL, TOTAL (INCL/EXCL GST), PAYMENT/CASH, or line-item sum from the same receipt; if the candidate is >5× or <1/5 of a corroborating value, demote it and prefer the next cross-variant candidate (helps repair single-digit OCR confusions like 1→7)."
    },
    {
      "skill": "image-ocr",
      "section": "Per-Image Pipeline with Null-Safe Failure",
      "change": "Reinforce in prose that unparseable fields MUST be written as Python None, never '' or 'None' or NaN, so the downstream writer emits real empty cells. One-sentence reminder with the task's grader semantics in mind."
    },
    {
      "skill": "xlsx",
      "section": "Strict-Schema Outputs (graded line-by-line)",
      "change": "Add one explicit bullet under the Contract Checklist cross-referencing the image-ocr null-safe rule: 'Fields that failed extraction upstream must arrive as None here; do not coerce to empty string or NaN before DataFrame construction.' No code change needed."
    }
  ],
  "confidence": {
    "observed_failures": "high",
    "root_causes": "high",
    "skill_defects": "high",
    "repair_recommendations": "medium",
    "notes": "Failure modes are directly supported by visible receipt text and by the recorded OCR variants in this window. Generalization of fixes beyond the four failing receipts (e.g. rounding-after-total, compound keyword tolerance, cross-variant voting) is well-motivated but will need validation on additional receipts outside this batch."
  }
}
